sp_SalvarPagamentosPedido	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_SalvarPagamentosPedido`(\n\n    IN p_idPedido         INT,\n\n    IN p_formaPagamento_id INT,\n\n    IN p_valor            DECIMAL(12,2)\n\n)\nBEGIN\n\n    INSERT INTO Pagamento (idPedido, formaPagamento_id, valor, dthPagamento)\n\n    VALUES (p_idPedido, p_formaPagamento_id, p_valor, NOW());\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
